  // Helper functions to extract data
  export const getCounties = (): County[] => {
    return kenyaAdministrativeData
  }
  
  export const getConstituenciesByCounty = (countyName: string): Constituency[] => {
    const county = kenyaAdministrativeData.find((c) => c.name === countyName)
    return county ? county.constituencies : []
  }
  
  export const getWardsByConstituency = (countyName: string, constituencyName: string): Ward[] => {
    const county = kenyaAdministrativeData.find((c) => c.name === countyName)
    if (!county) return []
  
    const constituency = county.constituencies.find((c) => c.name === constituencyName)
    return constituency ? constituency.wards : []
  }
  
  export const getPollingStationsByWard = (
    countyName: string,
    constituencyName: string,
    wardName: string,
  ): PollingStation[] => {
    const county = kenyaAdministrativeData.find((c) => c.name === countyName)
    if (!county) return []
  
    const constituency = county.constituencies.find((c) => c.name === constituencyName)
    if (!constituency) return []
  
    const ward = constituency.wards.find((w) => w.name === wardName)
    return ward ? ward.pollingStations : []
  }
  
  export const getCountyByName = (countyName: string): County | undefined => {
    return kenyaAdministrativeData.find((c) => c.name === countyName)
  }
  